// Package prune removes generated files that no generator run wrote
// this time. Emitters only ever write, so without it a removed
// resource's store, templates and actions would survive regeneration,
// keep compiling, and keep whatever behaviour they had.
package prune

import (
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// Pruned is Appendix C.2's op.generate.pruned, one line per removed file.
const Pruned = "removed %s: generated by an earlier run, and nothing generates it now"

// StaleMsg is Appendix C.2's op.generate.stale, one line per file
// --check finds that a run would remove.
const StaleMsg = "%s was generated by an earlier run and nothing generates it now; run rastrillo generate"

// headers maps an extension to the first line every file rastrillo
// generates with it begins with, in that format's comment syntax. The
// check is per extension so a file merely quoting a header in another
// syntax (a README that starts "# Code generated by rastrillo
// generate") is never taken for generated output.
var headers = map[string]string{
	".go":   "// Code generated by rastrillo generate",
	".sql":  "-- Code generated by rastrillo generate",
	".yaml": "# Code generated by rastrillo generate",
	".toml": "# Code generated by rastrillo generate",
	".html": "{{/* Code generated by rastrillo generate",
}

const sqlcHeader = "// Code generated by sqlc"

// Prune removes what Stale reports, then every directory that removal
// left empty, and returns the removed files the way Stale names them.
func Prune(genDir string, written []string, exclusiveStores []string) (removed []string, err error) {
	genDir = filepath.Clean(genDir)
	stale, err := find(genDir, written, exclusiveStores)
	if err != nil {
		return nil, err
	}
	for _, p := range stale {
		if err := os.Remove(p); err != nil {
			return removed, err
		}
		removed = append(removed, name(genDir, p))
		for dir := filepath.Dir(p); dir != genDir && strings.HasPrefix(dir, genDir); dir = filepath.Dir(dir) {
			if os.Remove(dir) != nil {
				break // not empty: an app file, or another generated file, still lives here
			}
		}
	}
	return removed, nil
}

// Stale returns, writing nothing, the files Prune would remove: each
// one under genDir that carries rastrillo's generated header and is
// not in written, carries sqlc's header outside the store directory
// of a resource that is exclusive in this run, or is gen/manifest.json
// when no run wrote it. Keeping sqlc output because its directory got
// some other generated file would be wrong: a store that turns
// mergeable gets store.go beside the old models.go and db.go, and the
// package declares Queries and New twice. Paths are slash-separated
// and relative to genDir's parent, as the messages name them.
func Stale(genDir string, written []string, exclusiveStores []string) ([]string, error) {
	stale, err := find(genDir, written, exclusiveStores)
	if err != nil {
		return nil, err
	}
	out := make([]string, len(stale))
	for i, p := range stale {
		out[i] = name(genDir, p)
	}
	return out, nil
}

// StaleError is nil when stale is empty, else an error of one
// op.generate.stale line per file, for --check to fail with.
func StaleError(stale []string) error {
	if len(stale) == 0 {
		return nil
	}
	lines := make([]string, len(stale))
	for i, f := range stale {
		lines[i] = fmt.Sprintf(StaleMsg, f)
	}
	return errors.New(strings.Join(lines, "\n"))
}

func find(genDir string, written []string, exclusiveStores []string) ([]string, error) {
	genDir = filepath.Clean(genDir)
	keep := make(map[string]bool, len(written))
	for _, p := range written {
		keep[filepath.Clean(p)] = true
	}
	sqlcDirs := make(map[string]bool, len(exclusiveStores))
	for _, d := range exclusiveStores {
		sqlcDirs[filepath.Clean(d)] = true
	}
	manifestJSON := filepath.Join(genDir, "manifest.json")

	var stale []string
	err := filepath.WalkDir(genDir, func(p string, d fs.DirEntry, err error) error {
		if os.IsNotExist(err) && p == genDir {
			return fs.SkipAll // nothing generated yet, so nothing is stale
		}
		if err != nil || !d.Type().IsRegular() || keep[p] {
			return err
		}
		// JSON has no comments to mark it; manifest.json is generated
		// exactly when a manifest resource exists, so its path decides.
		if p == manifestJSON {
			stale = append(stale, p)
			return nil
		}
		first, err := head(p)
		if err != nil {
			return err
		}
		if h, ok := headers[filepath.Ext(p)]; ok && strings.HasPrefix(first, h) {
			stale = append(stale, p)
		} else if filepath.Ext(p) == ".go" && strings.HasPrefix(first, sqlcHeader) && !sqlcDirs[filepath.Dir(p)] {
			stale = append(stale, p)
		}
		return nil
	})
	sort.Strings(stale)
	return stale, err
}

// head returns the start of the file, long enough for any header: a
// prefix compare needs no more, and reading a whole line would let one
// huge minified line fail the walk.
func head(path string) (string, error) {
	f, err := os.Open(path)
	if err != nil {
		return "", err
	}
	defer f.Close()
	buf := make([]byte, 64)
	n, err := io.ReadFull(f, buf)
	if err == io.EOF || err == io.ErrUnexpectedEOF {
		err = nil
	}
	return string(buf[:n]), err
}

func name(genDir, p string) string {
	rel, err := filepath.Rel(filepath.Dir(genDir), p)
	if err != nil {
		return filepath.ToSlash(p)
	}
	return filepath.ToSlash(rel)
}
